insert into public.venues (id, name, kind, quartier_id, address, status, verification, data_origin, opening_hours, admission, free_when, visit_tips, info_checked_on) values ('6339d3a1-cbc9-5600-892d-29624109a3ef', 'Tram-Museum Zürich', 'Museum', (select q.id from public.quartiers q join public.districts d on d.id = q.district_id where d.city_id = 'zurich' and q.name = 'Weinegg'), 'Forchstrasse 260, 8008 Zürich', 'published', 'provider_verified', 'provider:site', 'Mo, Mi, Sa, So 13–18 Uhr.', 'Kinder 0–5 Jahre: gratis · Kinder 6–16 Jahre CHF 7 · Erwachsene CHF 14 · Familieneintritt CHF 28 (max. 2 Erwachsene mit eigenen Kindern oder Enkeln).', 'Kinder bis 5 Jahre immer gratis. Freier Eintritt auch mit ZürichCard und Museumspässen.', 'Anreise mit Tram 4 Richtung Rehalp bis Burgwies. Das Museum ist teilweise rollstuhlgängig. Fahrten der Museumslinie 21: siehe Website.', '2026-11-18') on conflict (id) do update set opening_hours = excluded.opening_hours, admission = excluded.admission, free_when = excluded.free_when, visit_tips = excluded.visit_tips, info_checked_on = excluded.info_checked_on;
