insert into public.venues (id, name, kind, quartier_id, address, status, verification, data_origin, opening_hours, admission, free_when, visit_tips, info_checked_on) values ('363d269c-0f63-5e19-9832-2908701a595c', 'Uetliberg (Uto Kulm)', 'Ausflugsziel', null, null, 'published', 'provider_verified', 'provider:site', null, 'Zugfahrt: Tarif des ZVV, siehe szu.ch.', null, 'Anreise: Ab Zürich HB mit der Uetliberg-Bahn SZU (S10) von Gleis 22, 20 Minuten bis zur Endstation Uetliberg; der Fahrplan steht auf szu.ch. Der Gipfel Uto Kulm liegt auf 871 m ü. M. Auf dem Planetenweg (Angebot der SZU) sind «Sonne, Mond und Sterne zum Greifen nah». Zu Fuss ab Uitikon-Waldegg oder ab Albisgüetli etwa 45 Minuten. Das Hotel Uto Kulm empfiehlt den kostenlosen Parkplatz Feldermoos in Uitikon-Waldegg. Ob der Weg mit Kinderwagen geeignet ist, haben wir nicht geprüft.', '2026-11-18') on conflict (id) do update set opening_hours = excluded.opening_hours, admission = excluded.admission, free_when = excluded.free_when, visit_tips = excluded.visit_tips, info_checked_on = excluded.info_checked_on;
