insert into public.venues (id, name, kind, quartier_id, address, status, verification, data_origin, opening_hours, admission, free_when, visit_tips, info_checked_on) values ('b63c4a03-37f1-500c-a574-897abfb1e5a8', 'Ludothek Zürich Kreis 6', 'Ludothek', (select q.id from public.quartiers q join public.districts d on d.id = q.district_id where d.city_id = 'zurich' and q.name = 'Oberstrass'), 'Winterthurerstrasse 25, 8006 Zürich', 'published', 'provider_verified', 'provider:site', 'Do 15.30–17.30 Uhr (am Dienstag vorübergehend geschlossen). Einmal im Monat samstags 10–12 Uhr: 2026 am 21.11. und 12.12. In den Schulferien geschlossen.', 'Preise und Abo: siehe ludo-kreis6.ch.', null, 'Ausleihe von Spielsachen und Spielen. Der Lift ist nach 17 Uhr und samstags nicht in Betrieb: bei Bedarf während der Öffnungszeiten anrufen, dann wird er aktiviert. Das Team sucht Freiwillige (kostenloses Abo).', '2026-11-18') on conflict (id) do update set opening_hours = excluded.opening_hours, admission = excluded.admission, free_when = excluded.free_when, visit_tips = excluded.visit_tips, info_checked_on = excluded.info_checked_on;
